function resolve(u,ap){
  const act=new Set(['survey','handover']), why={};
  const add=(id,r)=>{if(!act.has(id)){act.add(id);why[id]=r}};
  const has=id=>u.has(id);
  const nb=has('newbuild'),pr=has('protected'); ap=(nb||pr||has('planning'))?'planning':'exempt';
  ['idesign','planning'].forEach(id=>{if(has(id))act.add(id)});
  ['extension','loft','strip','refurb','retrofit','garden','bcar','newbuild'].forEach(id=>{if(has(id))act.add(id)});
  const joinery=JOIN.filter(has);
  if(nb){add('site','Checks the site before you commit');add('planning','New homes always need planning permission');add('design','Drawings for the application');add('structural','Needed for new homes');add('tender','Needed before building starts');add('bcar','Required for new homes');add('services','New homes need new connections')}
  if(pr){add('conservation','Needed for a protected structure');add('planning','Works to a protected structure usually need planning permission');add('design','A conservation architect leads the drawings');add('tender','Needed before building starts')}
  const structural=['extension','loft','strip'].some(has);
  if(structural){add('design','Needed for structural work');add('structural','Needed for structural work');add(ap,'Every extension needs one of these');add('tender','Needed before building starts')}
  if(has('refurb')||has('retrofit')){add('tender','Needed before building starts')}
  if(has('garden')){add(ap,'Every garden room needs one of these')}
  if(ap==='planning'&&act.has('planning'))add('design','Drawings for the application');
  if(joinery.length){add('prod','Your '+joinery.join(', '));add('install','Fitting your joinery')}
  const needDesign=joinery.length||has('refurb')||has('retrofit')||has('garden')||act.has('tender');
  if(act.has('bcar')&&!act.has('tender'))add('tender','Needed before building starts');
  return {act,why,joinery};
}
function schedule(act,k){
  const s={},e={};
  ORDER.filter(id=>act.has(id)).forEach(id=>{
    const deps=M[id].d[0]==='*'?ORDER.filter(x=>x!==id&&act.has(x)):M[id].d.filter(x=>act.has(x));
    s[id]=deps.length?Math.max(...deps.map(x=>e[x])):0;
    e[id]=s[id]+M[id].w[k];
  });
  return {s,e};
}
const months=w=>Math.round(w/4.33*2)/2;
const fmtM=(a,b)=>a<6?a+'+ weeks':months(a)+'+ months';
function partnerCount(act){const s=new Set();ORDER.filter(id=>act.has(id)).forEach(id=>M[id].r.forEach(([n,t])=>{if(t===P)s.add(n)}));return s.size}
function facts(p){const u=new Set(p[3]);const {act}=resolve(u,p[4]);const lo=schedule(act,0),hi=schedule(act,1);return {time:fmtM(lo.e.handover,hi.e.handover),steps:act.size,team:partnerCount(act)}}
function pickImage(u){
  const h=id=>u.has(id);
  if(h('protected'))return 'protected';
  if(h('newbuild'))return 'newbuild';
  if(h('extension')&&(h('strip')||h('refurb')))return 'major';
  if(h('extension'))return 'extIn';
  if(h('strip'))return 'major';
  if(h('loft'))return 'loft';
  if(h('refurb')||h('retrofit'))return 'bought';
  if(h('garden'))return 'garden';
  return 'wardrobe';
}
