let LANG='en';const EN={};
const T=(k,fb)=>(LANG!=='en'&&I18N[LANG]&&I18N[LANG][k])||fb;
function applyLang(l){LANG=I18N[l]?l:'en';document.documentElement.lang=LANG;
  document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(!(k in EN))EN[k]=el.textContent;el.textContent=T(k,EN[k])});
  renderPackages();renderPresetBarLabels();update();show(si);translateDOM();if(window.AmbiensUI)window.AmbiensUI.languageChanged();try{localStorage.setItem('amb-lang',LANG)}catch(e){}}
const BA={idesign:['img6/idesign-before.webp','img6/idesign-after.webp'],planning:['img6/planning-before.webp','img6/planning-after.webp'],protected:['img6/protected-before.webp','img6/protected-after.webp'],newbuild:['img6/newbuild-before.webp','img6/newbuild-after.webp'],extension:['img6/extension-before.webp','img6/extension-after.webp'],loft:['img6/loft-before.webp','img6/loft-after.webp'],strip:['img6/strip-before.webp','img6/strip-after.webp'],refurb:['img6/refurb-before.webp','img6/refurb-after.webp'],retrofit:['img6/retrofit-before.webp','img6/retrofit-after.webp'],garden:['img6/garden-before.webp','img6/garden-after.webp'],bcar:['img6/bcar-before.webp','img6/bcar-after.webp'],kitchen:['img6/kitchen-before.webp','img6/kitchen-after.webp'],wardrobes:['img6/wardrobes-before.webp','img6/wardrobes-after.webp'],doors:['img6/doors-before.webp','img6/doors-after.webp']};
const dlg=document.getElementById('svcDlg');let dlgId=null,lastFocus=null;
function baHTML(id){const im=BA[id];
  const side=(cls,lab,src)=>`<div class="layer ${cls}">${src?`<img src="${src}" alt="${lab} – ${DETAIL[id].t}">`:`<div class="ph-slot">${lab} image</div>`}</div>`;
  return side('before','Before',im&&im[0])+side('after','After',im&&im[1])+'<span class="tag2 tb">Before</span><span class="tag2 ta">After</span><span class="tag2 tc">Concept image</span><span class="handle"></span><input type="range" min="0" max="100" value="50" aria-label="Compare before and after">';}
function openSvc(id,pricingCategory=null){const d=DETAIL[id];if(!d)return;dlgId=id;dlgPricingCategory=pricingCategory;lastFocus=document.activeElement;
  document.getElementById('dlgGrp').textContent=d.g;document.getElementById('dlgTitle').textContent=d.t;document.getElementById('dlgLead').textContent=d.lead;const sub=CHOICES.flatMap(x=>x[1]).find(x=>x[0]===id);document.getElementById('dlgSub').textContent=sub?sub[2]:'';
  document.getElementById('dlgInc').innerHTML=d.inc.map(x=>`<li>${x}</li>`).join('');
  document.getElementById('dlgWhy').textContent=d.why;document.getElementById('dlgRes').textContent=d.res;document.getElementById('dlgWho').textContent=d.who;
  const ba=document.getElementById('dlgBA');ba.innerHTML=baHTML(id);ba.style.setProperty('--x','50%');
  ba.querySelector('input').addEventListener('input',e=>ba.style.setProperty('--x',e.target.value+'%'));
  document.getElementById('dlgAdd').textContent=user.has(id)?'Already in my plan':'Add to my plan';
  if(pricingCategory==='refurb_with_extension'){
    document.getElementById('dlgTitle').textContent='Whole-house refurbishment with extension';
    document.getElementById('dlgLead').textContent=PRESETS.find(p=>p[0]==='major')[2];
    document.getElementById('dlgInc').replaceChildren(...[...new Set([...DETAIL.refurb.inc,...DETAIL.extension.inc])].map(x=>{const li=document.createElement('li');li.textContent=x;return li}));
  }
  renderServiceBudget(id,pricingCategory);dlg.showModal();}
document.getElementById('dlgClose').addEventListener('click',()=>dlg.close());
dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close()});
dlg.addEventListener('close',()=>{if(lastFocus)lastFocus.focus()});
document.getElementById('dlgAdd').addEventListener('click',()=>{if(dlgPricingCategory==='refurb_with_extension')choose('major');else{user.add(dlgId);preset=null;update()}dlg.close();window.AmbiensUI.navigate('/planner/');});
function askAboutService(service){
  const message=document.getElementById('f-msg'),context=document.getElementById('formServiceInterest');
  const enquiry=trs('I would like to know more about:')+' '+trs(service)+'.';
  const addition=(message.value?'\n\n':'')+enquiry;
  // Preserve the complete draft and its length limit; the selected service also
  if(context.value!==service&&!message.value.includes(enquiry)&&
    (message.maxLength<0||message.value.length+addition.length<=message.maxLength))message.value+=addition;
  context.value=service;
}
document.getElementById('dlgAsk').addEventListener('click',()=>{
  askAboutService(dlgPricingCategory==='refurb_with_extension'?'Whole-house refurbishment with extension':DETAIL[dlgId].t);
  dlg.close();
});
// A service with its own page is a link; the others open their details.
function serviceEntry(id,d){
  const page=SERVICE_PAGE[id],el=document.createElement(page?'a':'button');
  if(page)el.href=page;else{el.type='button';el.addEventListener('click',()=>openSvc(id))}
  el.textContent=d.t;return el;
}
function renderSvcIndex(){const el=document.getElementById('svcIndex');el.innerHTML='';
  ['Design','Build','Joinery'].forEach(g=>{const col=document.createElement('div');col.innerHTML=`<div class="gt">${g}</div>`;
    Object.entries(DETAIL).filter(([,d])=>d.g===g).forEach(([id,d])=>{const b=serviceEntry(id,d);b.className='svc-btn';col.appendChild(b)});el.appendChild(col)});}

