Object.entries(FEEDBACK_TRANSLATIONS).forEach(([lang,copy])=>Object.assign(L[lang],copy));
const ORIG=new WeakMap();
function trs(s){if(LANG==='en'||!s)return s;const d=L[LANG];if(!d)return s;if(d[s]!==undefined)return d[s];let m;
  const sep=(LANG==='zh-Hans'||LANG==='zh-Hant'||LANG==='ja')?'、':', ';
  if((m=s.match(/^(\d+) stages$/)))return m[1]+' '+d['stages'];
  if((m=s.match(/^(.*) \((\d+)\)$/))&&d[m[1]]!==undefined)return d[m[1]]+' ('+m[2]+')';
  if((m=s.match(/^Open (.+) in the planner$/)))return d['Open {x} in the planner'].replace('{x}',trs(m[1]));
  if((m=s.match(/^(Details|Included|BOLONI joinery made to measure): (.+)$/)))return d[m[1]]+': '+m[2].split(', ').map(trs).join(sep);
  if((m=s.match(/^Slide (\d)$/)))return d['Slide']+' '+m[1];
  if((m=s.match(/^Approx\. (\d+)–(\d+) weeks$/)))return d['Approx. {low}–{high} weeks'].replace('{low}',m[1]).replace('{high}',m[2]);
  if(s.includes(' · ')){const a=s.split(' · ');if(a.every(x=>d[x]!==undefined))return a.map(x=>d[x]).join(' · ')}
  if(s.includes(', ')){const a=s.split(', ');if(a.every(x=>d[x]!==undefined))return a.map(x=>d[x]).join(sep)}
  return s}
let trBusy=false;
function translateDOM(root){if(trBusy)return;trBusy=true;try{
  const w=document.createTreeWalker(root||document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const pe=n.parentElement;return pe&&!pe.closest('script,style,#lang,#heroTitle,[data-pricing-root],[data-i18n]')?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});
  let n;while((n=w.nextNode())){let saved=ORIG.get(n);if(!saved||n.data!==saved.last){saved={source:n.data,last:n.data};ORIG.set(n,saved)}const o=saved.source;const k=o.replace(/\s+/g,' ').trim();if(!k)continue;
    const lead=o.match(/^\s*/)[0],trail=o.match(/\s*$/)[0];const v=LANG==='en'?o:lead+trs(k)+trail;if(n.data!==v)n.data=v;saved.last=v}
  document.querySelectorAll('[aria-label],[placeholder]').forEach(e=>{if(e.closest('[data-pricing-root]'))return;['aria-label','placeholder'].forEach(a=>{if(!e.hasAttribute(a))return;const key='data-en-'+a;if(!e.hasAttribute(key))e.setAttribute(key,e.getAttribute(a));const o=e.getAttribute(key);const v=LANG==='en'?o:trs(o);if(e.getAttribute(a)!==v)e.setAttribute(a,v)})});
}finally{trBusy=false}}
let trTimer=null;
new MutationObserver(()=>{if(LANG==='en'||trBusy)return;clearTimeout(trTimer);trTimer=setTimeout(()=>translateDOM(),0)}).observe(document.body,{childList:true,subtree:true,characterData:true});
function renderPackages(){
  const el=document.getElementById('pks');el.innerHTML='';
  PRESETS.forEach(p=>{
    const f=facts(p), im=IMG[p[5]];
    const t=document.createElement('article');t.className='tile';t.dataset.id=p[0];
    t.innerHTML=`<button class="img" type="button" aria-label="Open ${p[1]} in the planner"><img src="${im[0]}" alt="${im[1]}" loading="lazy"></button>
      <div class="row"><h3>${p[1]}</h3><span class="meta">${f.steps} stages</span></div>
      <p>${p[2]}</p><button class="open" type="button">Open in planner</button>`;
    const go=()=>window.AmbiensUI.navigate('/planner/'+p[0]+'/');
    t.querySelector('.img').addEventListener('click',go);t.querySelector('.open').addEventListener('click',go);
    el.appendChild(t);
  });
}
function renderPresetBar(){const el=document.getElementById('presetbar');PRESETS.forEach(p=>{const b=document.createElement('button');b.type='button';b.dataset.id=p[0];b.textContent=p[1];b.addEventListener('click',()=>window.AmbiensUI.navigate('/planner/'+p[0]+'/'));el.appendChild(b)})}
