      l.innerHTML=`<input type="checkbox" id="m-${id}" ${user.has(id)||locked?'checked':''} ${locked?'disabled':''}><span><span>${t}</span><small${locked?' class="why"':''}>${locked?'Included: '+why[id]:sub}</small></span>`;
      if(locked)l.classList.add('auto');
      l.querySelector('input').addEventListener('change',ev=>{ev.target.checked?user.add(id):user.delete(id);preset=null;update();if(window.AmbiensUI)window.AmbiensUI.customised()});
      const row=document.createElement('div');row.className='modrow';row.appendChild(l);
