function stageDuration(weeks){
  const locale={en:'en-IE',fr:'fr-FR',de:'de-DE',it:'it-IT',es:'es-ES','zh-Hans':'zh-CN','zh-Hant':'zh-TW',ja:'ja-JP'}[LANG]||'en-IE';
  const number=n=>new Intl.NumberFormat(locale).format(n);
  if(weeks[0]===weeks[1])return trs('Approx. {weeks} week').replace('{weeks}',number(weeks[0]));
  return trs('Approx. {low}–{high} weeks').replace('{low}',number(weeks[0])).replace('{high}',number(weeks[1]));
}
function render(){
  const {act,joinery}=resolve(user,approval);const lo=schedule(act,0),hi=schedule(act,1);const total=hi.e.handover;
  const ids=ORDER.filter(id=>act.has(id));document.getElementById('sSteps').textContent=ids.length;
  const roles=new Map();ids.forEach(id=>M[id].r.forEach(([n,t])=>{if(!roles.has(n))roles.set(n,{t,s:[]});roles.get(n).s.push(M[id].n)}));
  document.getElementById('sTeam').textContent=[...roles.values()].filter(r=>r.t===P).length;
  const g=document.getElementById('gantt');g.replaceChildren();
  ids.forEach((id,index)=>{
    const row=document.createElement('li');row.className='stage-item';row.dataset.stage=id;
    const number=document.createElement('span');number.className='stage-number';number.textContent=String(index+1).padStart(2,'0');number.setAttribute('aria-hidden','true');
    const title=document.createElement('h4');title.textContent=id==='prod'&&joinery.length?M[id].n+': '+joinery.map(j=>SHORT[j].toLowerCase()).join(', '):M[id].n;
    const duration=document.createElement('p');duration.className='stage-duration';duration.textContent=stageDuration(M[id].w);duration.dataset.minWeeks=M[id].w[0];duration.dataset.maxWeeks=M[id].w[1];
    const who=document.createElement('p');who.className='stage-owner';who.textContent=M[id].r.map(r=>r[0]).join(', ');
    row.append(number,title,duration,who);g.appendChild(row);
  });renderPhoto();
}
